import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.D3fmyz3M.js";const p=JSON.parse('{"title":"学习路线","description":"五个阶段、七套示例，从建立认知到源码级精通。","frontmatter":{"title":"学习路线","description":"五个阶段、七套示例，从建立认知到源码级精通。"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1792674288000}'),i={name:"guide/index.md"};function o(l,t,n,h,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h1><p>微前端不是一个库，而是一组<strong>把多个独立应用组装成一个产品</strong>的工程方法。学习它最容易踩的坑，是一上来就抄配置：能跑，但不知道为什么，出问题也定位不了。</p><p>本教程按“认知 → 原理 → 实战 → 工程 → 精通”组织，每一层都能独立停下，也都为下一层服务。</p><h2 id="五个阶段" tabindex="-1">五个阶段 <a class="header-anchor" href="#五个阶段" aria-label="Permalink to &quot;五个阶段&quot;">​</a></h2><h3 id="阶段一-建立认知" tabindex="-1">阶段一：建立认知 <a class="header-anchor" href="#阶段一-建立认知" aria-label="Permalink to &quot;阶段一：建立认知&quot;">​</a></h3><p>先回答三个问题：</p><ol><li>我们的痛点到底是“团队协作”还是“技术栈统一”？</li><li>微前端能解决什么，不能解决什么？</li><li>现在做，收益是否大于复杂度成本？</li></ol><p>对应章节：<a href="/micro-frontend-docs/guide/what-is">微前端是什么</a>、<a href="/micro-frontend-docs/guide/when-to-use">何时用，何时不用</a>、<a href="/micro-frontend-docs/guide/evolution">技术演进</a>。</p><h3 id="阶段二-理解原理" tabindex="-1">阶段二：理解原理 <a class="header-anchor" href="#阶段二-理解原理" aria-label="Permalink to &quot;阶段二：理解原理&quot;">​</a></h3><p>所有方案都在处理五件事：</p><table tabindex="0"><thead><tr><th>关注点</th><th>典型问题</th></tr></thead><tbody><tr><td>加载</td><td>子应用的 HTML、JS、CSS 怎么被取回并执行？</td></tr><tr><td>隔离</td><td>全局变量、定时器、事件、样式怎么不互相污染？</td></tr><tr><td>路由</td><td>主应用与子应用谁管 URL？刷新后怎么恢复？</td></tr><tr><td>通信</td><td>props、全局状态、事件总线怎么选？</td></tr><tr><td>治理</td><td>版本、灰度、监控、回滚怎么落地？</td></tr></tbody></table><p>对应章节：<a href="/micro-frontend-docs/principles/">原理总览</a>。</p><h3 id="阶段三-动手实战" tabindex="-1">阶段三：动手实战 <a class="header-anchor" href="#阶段三-动手实战" aria-label="Permalink to &quot;阶段三：动手实战&quot;">​</a></h3><p>七套示例按“隔离强度”和“改造成本”排序，建议至少完整跑通三套：</p><ol><li><a href="/micro-frontend-docs/schemes/iframe">iframe</a>：理解隔离的基线。</li><li><a href="/micro-frontend-docs/schemes/qiankun">qiankun</a>：国内最常见的生产方案。</li><li><a href="/micro-frontend-docs/schemes/module-federation">Module Federation</a>：构建时集成的另一条路。</li></ol><p>其余方案按团队技术栈取舍阅读。</p><h3 id="阶段四-工程落地" tabindex="-1">阶段四：工程落地 <a class="header-anchor" href="#阶段四-工程落地" aria-label="Permalink to &quot;阶段四：工程落地&quot;">​</a></h3><p>能跑 demo 和能上线之间，差着部署、监控、性能与治理。对应章节：<a href="/micro-frontend-docs/advanced/">工程化进阶</a>。</p><h3 id="阶段五-直达精通" tabindex="-1">阶段五：直达精通 <a class="header-anchor" href="#阶段五-直达精通" aria-label="Permalink to &quot;阶段五：直达精通&quot;">​</a></h3><p>读源码、做迁移、查故障、写选型报告。对应章节：<a href="/micro-frontend-docs/mastery/">直达精通</a>。</p><h2 id="建议节奏" tabindex="-1">建议节奏 <a class="header-anchor" href="#建议节奏" aria-label="Permalink to &quot;建议节奏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>周次</th><th>任务</th><th>产出</th></tr></thead><tbody><tr><td>第 1 周</td><td>读完 guide 与 principles，跑通 iframe</td><td>能讲清隔离与通信的基本取舍</td></tr><tr><td>第 2 周</td><td>跑通 qiankun 与 micro-app</td><td>能解释 HTML Entry 与沙箱差异</td></tr><tr><td>第 3 周</td><td>跑通 Module Federation，读 single-spa 源码</td><td>能对比“运行时集成”与“构建时集成”</td></tr><tr><td>第 4 周</td><td>做一次小范围迁移方案</td><td>选型报告 + 迁移与回滚计划</td></tr></tbody></table><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>Vue 3 或 React 18 的基础开发能力。</li><li>了解 Vite 的基本配置与构建产物。</li><li>知道浏览器同源策略、<code>postMessage</code>、<code>Shadow DOM</code> 的大致概念。</li><li>能使用 Git 与 CI（本教程用 GitHub Actions 演示）。</li></ul><h2 id="配套示例怎么用" tabindex="-1">配套示例怎么用 <a class="header-anchor" href="#配套示例怎么用" aria-label="Permalink to &quot;配套示例怎么用&quot;">​</a></h2><p>每套示例都包含一个主应用和一到两个子应用，端口固定。启动方式见各方案页的“运行”小节。</p><p>推荐练习方式：</p><ol><li>先按文档跑通。</li><li>改一个变量，观察日志面板的变化。</li><li>故意制造一次样式冲突或全局变量污染。</li><li>用原理章节解释你看到的现象。</li></ol><h2 id="阅读约定" tabindex="-1">阅读约定 <a class="header-anchor" href="#阅读约定" aria-label="Permalink to &quot;阅读约定&quot;">​</a></h2><ul><li>代码块中的路径均相对于仓库根目录。</li><li>“坑点”小节只写真实会遇到的问题，不写理论风险。</li><li>每篇方案末尾都有“验证清单”，全部通过才算真正跑通。</li></ul>',30)])])}const f=a(i,[["render",o]]);export{p as __pageData,f as default};
